import {CONCEPT_MODES} from './studio-concept.js?v=1';
import {createStudioIcon} from './studio-icons.js?v=24';
import {assetURL,createAssetPicker} from './studio-assets.js?v=7';
export const DESIGN_MODES=[['clay','Kết xuất đất sét','Convert the source to a monochrome neutral grey clay 3D render. Preserve exact silhouette, pose, camera, composition, geometry and all modeled details. Remove photographic colors and textures. Matte unpainted clay material, soft studio light, ambient occlusion, light neutral background. This is a rendered reference image, not a 3D model file.'],['moodboard','Bảng cảm hứng','Create a cohesive visual concept moodboard from supplied materials and style references. Clear hero focus, controlled palette, balanced spacing and supporting texture studies. No invented captions or text.'],['render','Kết xuất','Render the supplied source design into a polished finished visualization. Preserve its geometry, proportions, functional details and camera. Apply the supplied material and style references only to the relevant surfaces.'],['restyle','Đổi phong cách','Restyle the source using the supplied material and style references. Preserve the source geometry, layout, proportions, recognizable identity and camera. Transfer only the requested material, texture, finish, palette and visual language.'],['textstyle','Kiểu chữ','Restyle typography and graphic treatment using the supplied references. Preserve all original wording, spelling and reading order. Preserve the design structure unless the brief requests changes.'],['relayout','Đổi bố cục','Create an alternative layout of the supplied design. Keep all required content, exact wording, brand identity, products and provided materials. Change hierarchy, alignment, spacing and composition intentionally.'],['sketch','Phác thảo → Thiết kế','Transform the source sketch into a finished design. Follow its contour, proportions, perspective and annotated requirements. Interpret rough strokes as construction guidance, not visible final line artifacts.'],['layout','Bố cục phác → Thiết kế','Use the source layout sketch as a spatial blueprint. Preserve relative placement, hierarchy, reading order and proportions. Replace placeholders with finished design elements using supplied materials and references.']];
export function buildDesignPrompts({mode='clay',brief='',refs=[],roles={},count=1}){if(!refs.length)throw Error('Thêm ảnh gốc hoặc sketch trước.');if(['restyle','textstyle'].includes(mode)&&refs.length<2)throw Error('Thêm ít nhất một ảnh chất liệu hoặc phong cách.');const item=DESIGN_MODES.find(x=>x[0]===mode);if(!item)throw Error('Chọn chức năng Design.');const contract=refs.map((r,i)=>'@'+r.tag+' = '+(i===0?'SOURCE DESIGN: primary geometry, composition and content':roles[r.tag]||'STYLE REFERENCE: visual language only')).join('\n');return Array.from({length:Math.min(4,Math.max(1,Number(count)||1))},(_,i)=>'DESIGN TASK: '+item[2]+'\nINPUT ROLES:\n'+contract+'\nUSER BRIEF:\n'+brief+'\nOUTPUT: One complete finished image, no collage, no before/after, no extra labels or watermarks. '+(count>1?'Design option '+(i+1)+' of '+count+'. Develop a distinct coherent alternative while honoring every locked source requirement.':'Preserve source details except explicitly requested changes.'));}
export function createDesignControls(React){const{createElement:h}=React,Icon=createStudioIcon(React);return function Design({mode,onMode,disabled}){const groups=[['Kết xuất & phong cách',['clay','render','restyle','moodboard']],['Bố cục & phác thảo',['textstyle','relayout','sketch','layout']]],icons={clay:'product',render:'enhance',restyle:'color',moodboard:'grid',textstyle:'prompt',relayout:'sliders',sketch:'detail',layout:'background'};return h('section',{className:'design-controls'},h('div',{className:'design-tool-section'},h('h3',null,'Phát triển concept'),h('div',{className:'design-mode-grid concept-mode-grid'},...CONCEPT_MODES.map(([id,label,icon])=>h('button',{key:id,type:'button','aria-pressed':mode===id,disabled,onClick:()=>onMode(id)},h(Icon,{name:icon,size:17}),h('span',null,label))))),...groups.map(([title,ids])=>h('div',{className:'design-tool-section',key:title},h('h3',null,title),h('div',{className:'design-mode-grid'},...ids.map(id=>{const label=DESIGN_MODES.find(x=>x[0]===id)[1];return h('button',{key:id,type:'button','aria-pressed':mode===id,title:label,onClick:()=>onMode(id),disabled},h(Icon,{name:icons[id],size:17}),h('span',null,label))})))));};}
